/* ================= INVENTORY ================= */
S.inv={q:'',cat:'All',st:'All',tab:'products'};
PAGES.inventory=()=>{const ps=S.products;const val=sum(ps,p=>p.stock*p.cost),retail=sum(ps,p=>p.stock*p.price);const low=ps.filter(p=>p.stock>0&&p.stock<p.min).length,oos=ps.filter(p=>p.stock<=0).length;return `<div class="page">${head('Catalog & stock control','Products & Inventory','Variants, batches, barcodes, pricing tiers and real-time stock across every store.',`<button class="btn" onclick="importCSVPrompt()">${ic('upload',16)} Import CSV</button><button class="btn" onclick="exportCSV('inventory',[['SKU','Barcode','Name','Category','Cost','Retail','Wholesale','Stock','Min','Max','Batch','Expiry (days)'],...S.products.map(p=>[p.sku,p.barcode,p.name,p.cat,p.cost,p.price,p.wholesale,p.stock,p.min,p.max,p.batch,p.expiry])])">${ic('download',16)} Export</button><button class="btn pri" onclick="addProduct()">${ic('plus',16,2.4)} Add product</button>`)}<section class="grid g4 mb">${kpi('Stock value (cost)',cu(val,'money'),'+3.8%','package','var(--primary)',[5,6,6,7,6,7,8,8],0,'retail '+moneyK(retail))}${kpi('Active SKUs',cu(ps.length),'+2','layers','var(--teal)',null,1,Object.keys(CATS).length+' categories')}${kpi('Low stock',cu(low),'','alert','var(--warning)',null,2,'below minimum level')}${kpi('Out of stock',cu(oos),'','x','var(--danger)',null,3,'lost sales risk')}</section><section class="card pad rv" style="--i:4"><div class="row between wrap mb"><div class="seg">${[['products','Products'],['moves','Stock movements'],['labels','Barcode labels']].map(([k,l])=>`<button class="${S.inv.tab===k?'on':''}" onclick="S.inv.tab='${k}';refresh()">${l}</button>`).join('')}</div>${S.inv.tab==='products'?`<div class="row wrap"><label class="search">${ic('search',16)}<input placeholder="Search name, SKU, barcode…" value="${esc(S.inv.q)}" oninput="S.inv.q=this.value;$('#itab').innerHTML=invTable()"></label><select class="sel" style="width:auto" onchange="S.inv.cat=this.value;$('#itab').innerHTML=invTable()"><option>All</option>${Object.keys(CATS).map(c=>`<option ${S.inv.cat===c?'selected':''}>${c}</option>`).join('')}</select><select class="sel" style="width:auto" onchange="S.inv.st=this.value;$('#itab').innerHTML=invTable()">${['All','In stock','Low stock','Out of stock','Overstock'].map(s=>`<option ${S.inv.st===s?'selected':''}>${s}</option>`).join('')}</select></div>`:''}</div><div id="itab">${S.inv.tab==='products'?invTable():S.inv.tab==='moves'?movesTable():labelsGrid()}</div></section>${foot()}</div>`};
function invStatus(p){return p.stock<=0?'Out of stock':p.stock<p.min?'Low stock':p.stock>p.max?'Overstock':'In stock'}
function invTable(){const q=S.inv.q.toLowerCase();const l=S.products.filter(p=>(S.inv.cat==='All'||p.cat===S.inv.cat)&&(S.inv.st==='All'||invStatus(p)===S.inv.st)&&(p.name+p.sku+p.barcode).toLowerCase().includes(q));if(!l.length)return `<div class="empty"><div class="e-ic">${ic('package',26)}</div><b>No products found</b></div>`;return `<div class="tw"><table><thead><tr><th>Product</th><th>SKU / Barcode</th><th class="tr">Cost</th><th class="tr">Retail</th><th class="tr">Wholesale</th><th class="tr">Margin</th><th>Stock level</th><th>Status</th><th></th></tr></thead><tbody>${l.map((p,i)=>{const m=(p.price/(1+S.settings.taxRate/100)-p.cost)/(p.price/(1+S.settings.taxRate/100))*100;const pct=Math.min(100,p.stock/p.max*100);return `<tr class="rv" style="--i:${Math.min(i,14)}"><td><div class="pcell click" onclick="productDrawer(${p.id})" style="cursor:pointer"><div class="pimg" style="background:${CATS[p.cat].tone}">${p.emoji}</div><div><b>${esc(p.name)}</b><small>${p.cat}${p.variants.length?` · ${p.variants.length} variants`:''}</small></div></div></td><td><b style="font-family:monospace;font-size:12px">${p.sku}</b><div class="xs muted" style="font-family:monospace">${p.barcode}${p.extraBarcodes.length?' +'+p.extraBarcodes.length:''}</div></td><td class="tr num">${money(p.cost)}</td><td class="tr num"><b>${money(p.price)}</b></td><td class="tr num">${money(p.wholesale)}</td><td class="tr"><span class="${m>35?'up':m<25?'down':''} b">${m.toFixed(1)}%</span></td><td><div class="row" style="gap:10px"><div class="bar-mini" style="width:90px;--c:${p.stock<p.min?'var(--warning)':p.stock<=0?'var(--danger)':'var(--success)'}"><i style="width:${pct}%"></i></div><span class="num sm"><b>${p.stock}</b> <span class="muted">/ ${p.max}</span></span></div></td><td>${stockBadge(p)}</td><td class="tr"><button class="btn xs" onclick="adjustStock(${p.id})">${ic('edit',13)} Adjust</button> <button class="btn xs ghost" onclick="printLabel(${p.id})" title="Print label">${ic('tag',13)}</button></td></tr>`}).join('')}</tbody></table></div>`}
function movesTable(){const tc={Sale:'',Received:'ok',Return:'info','Write-off':'bad','Transfer out':'warn','Transfer in':'info','Count correction':'warn',Adjustment:'pri'};return `<div class="tw"><table><thead><tr><th>Time</th><th>Product</th><th>Movement</th><th class="tr">Qty</th><th>Reference</th><th>User</th></tr></thead><tbody>${S.movements.slice(0,40).map((m,i)=>{const p=P(m.pid);return `<tr class="rv" style="--i:${Math.min(i,14)}"><td>${fmtTime(m.time)}</td><td><div class="pcell"><div class="pimg" style="width:32px;height:32px;font-size:16px;background:${CATS[p.cat].tone}">${p.emoji}</div><b>${esc(p.name)}</b></div></td><td><span class="badge ${tc[m.type]||''}">${m.type}</span></td><td class="tr num b ${m.qty>0?'up':'down'}">${m.qty>0?'+':''}${m.qty}</td><td>${m.reason}</td><td>${m.user}</td></tr>`}).join('')}</tbody></table></div>`}
function labelsGrid(){return `<div class="grid g4">${S.products.slice(0,12).map((p,i)=>`<div class="card pad hov rv" style="--i:${i};text-align:center;background:var(--surface-2)"><div class="receipt" style="padding:14px;max-width:none;box-shadow:none;border-radius:12px"><b style="font-family:Inter">${esc(p.name)}</b><div style="font:800 20px Inter;margin:4px 0">${money(p.price)}</div>${barcodeSVG(p.barcode,180,46)}</div><button class="btn sm" style="margin-top:12px" onclick="printLabel(${p.id})">${ic('printer',14)} Print label</button></div>`).join('')}</div>`}
function printLabel(id){const p=P(id);modal({title:'Shelf label',sub:'Zebra ZD421 · 58 × 40 mm',size:'sm',icon:'tag',body:`<div class="rec-prev"><div class="receipt" style="max-width:260px;text-align:center"><b style="font-family:Inter;font-size:14px">${esc(p.name)}</b><div style="font:800 30px Inter;margin:6px 0">${money(p.price)}</div><div style="font-size:10px;color:#666">${p.sku} · Batch ${p.batch}</div>${barcodeSVG(p.barcode,200,52)}</div></div><label class="field mt">Copies<input class="input" type="number" value="4" min="1" id="lbl-n"></label>`,foot:`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn pri" onclick="toast('Sent '+$('#lbl-n').value+' labels to Zebra ZD421');closeModal()">${ic('printer',16)} Print</button>`})}
function productDrawer(id){const p=P(id);const shares=[.41,.27,.2,.12];drawer(`<div class="dh"><div class="pimg" style="width:56px;height:56px;font-size:30px;background:${CATS[p.cat].tone}">${p.emoji}</div><div style="flex:1"><h2 class="display" style="margin:0;font-size:19px">${esc(p.name)}</h2><div class="sm muted">${p.cat} · ${p.sku}</div><div style="margin-top:6px">${stockBadge(p)}</div></div><button class="btn ghost sm icon" onclick="closeDrawer()">${ic('x',16)}</button></div><div class="db"><div class="kv"><div><small>Retail price</small><b>${money(p.price)}</b></div><div><small>Wholesale price</small><b>${money(p.wholesale)}</b></div><div><small>Purchase cost</small><b>${money(p.cost)}</b></div><div><small>Sold (30 days)</small><b>${num(p.sold30)}</b></div></div><div class="sec-t">Sales trend</div>${area({series:[{name:'Units',data:Array.from({length:14},(_,i)=>Math.max(1,p.sold30/30*(0.6+Math.sin(i/1.7+id)*.3+((i*id)%7)/14))),c:CATS[p.cat].c}],labels:lastDays(14),h:150,fmt:v=>Math.round(v)})}<div class="sec-t">Stock by branch</div>${S.branches.map((b,i)=>{const q=Math.round(p.stock*shares[i]);return `<div class="li"><span class="badge" style="background:${b.c}22;color:${b.c};width:44px;justify-content:center">${b.id}</span><span style="flex:1">${b.name}</span><div class="bar-mini" style="width:90px;--c:${b.c}"><i style="width:${Math.min(100,q/Math.max(1,p.max*shares[i])*100)}%"></i></div><b class="num" style="width:40px;text-align:right">${q}</b></div>`}).join('')}<div class="sec-t">Identification</div><div class="kv"><div><small>Batch / lot</small><b style="font-size:14px">${p.batch}</b></div><div><small>Expires in</small><b style="font-size:14px;color:${p.expiry<=3?'var(--danger)':'inherit'}">${p.expiry} days</b></div><div><small>Min / max level</small><b style="font-size:14px">${p.min} / ${p.max}</b></div><div><small>Barcodes</small><b style="font-size:12px;font-family:monospace">${[p.barcode,...p.extraBarcodes].join('<br>')}</b></div></div>${p.variants.length?`<div class="sec-t">Variants</div><div class="row wrap">${p.variants.map(v=>`<span class="chip">${v}</span>`).join('')}</div>`:''}</div><div class="df"><button class="btn" onclick="closeDrawer();setTimeout(()=>editProduct(${p.id}),260)">${ic('edit',15)} Edit</button><button class="btn" onclick="closeDrawer();setTimeout(()=>adjustStock(${p.id}),260)">${ic('package',15)} Adjust stock</button><button class="btn" onclick="closeDrawer();setTimeout(()=>printLabel(${p.id}),260)">${ic('tag',15)} Label</button></div>`);setTimeout(after,30)}
function adjustStock(id){const p=P(id);modal({title:'Adjust stock',sub:`${esc(p.name)} · currently ${p.stock} units`,icon:'package',body:`<div class="fgrid"><label class="field">Adjustment type<select class="sel" id="aj-t"><option value="add">Add stock (+)</option><option value="remove">Remove stock (−)</option><option value="set">Set exact count</option></select></label><label class="field">Quantity<input class="input" type="number" min="0" id="aj-q" value="10"></label><label class="field full">Reason<select class="sel" id="aj-r"><option>Goods received</option><option>Cycle count correction</option><option>Damaged</option><option>Lost / stolen</option><option>Expired</option><option>Internal use</option></select></label><label class="field full">Note <small>(optional)</small><input class="input" id="aj-n" placeholder="e.g. Shelf count after delivery"></label></div>`,foot:`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn pri" onclick="saveAdjust(${id})">Save adjustment</button>`})}
function saveAdjust(id){const p=P(id),t=$('#aj-t').value,q=Math.round(+$('#aj-q').value),r=$('#aj-r').value;if(!(q>=0))return toast('Enter a valid quantity','warn');const before=p.stock;p.stock=t==='add'?p.stock+q:t==='remove'?Math.max(0,p.stock-q):q;const d=p.stock-before;const type=['Damaged','Lost / stolen','Expired'].includes(r)?'Write-off':r==='Goods received'?'Received':r.startsWith('Cycle')?'Count correction':'Adjustment';S.movements.unshift({time:new Date(),pid:id,type,qty:d,reason:r,user:'Alex Morgan'});if(type==='Write-off')S.waste.unshift({time:new Date(),pid:id,qty:-d,reason:r,user:'Alex Morgan'});audit('stock',`Stock ${d>=0?'+':''}${d} · ${p.name} (${r})`,p.sku);closeModal();toast(`${esc(p.name)}: ${before} → <b>${p.stock}</b> units`);refresh()}
function productForm(p={}){return `<div class="fgrid"><label class="field full">Product name<input class="input" id="np-name" value="${esc(p.name||'')}" placeholder="e.g. Organic Granola 500g"></label><label class="field">Category<select class="sel" id="np-cat">${Object.keys(CATS).map(c=>`<option ${p.cat===c?'selected':''}>${c}</option>`).join('')}</select></label><label class="field">SKU<input class="input" id="np-sku" value="${esc(p.sku||'')}" placeholder="Auto-generated if blank"></label><label class="field">Purchase cost<input class="input" type="number" step=".01" id="np-cost" value="${p.cost??''}" placeholder="0.00"></label><label class="field">Retail price<input class="input" type="number" step=".01" id="np-price" value="${p.price??''}" placeholder="0.00"></label><label class="field">Wholesale price<input class="input" type="number" step=".01" id="np-whl" value="${p.wholesale??''}" placeholder="Optional"></label><label class="field">Opening stock<input class="input" type="number" id="np-stock" value="${p.stock??''}" placeholder="0" ${p.id?'disabled':''}></label><label class="field">Minimum level<input class="input" type="number" id="np-min" value="${p.min??20}"></label><label class="field">Maximum level<input class="input" type="number" id="np-max" value="${p.max??150}"></label><label class="field">Barcode<div class="row"><input class="input" id="np-bc" value="${p.barcode||''}" placeholder="Scan or generate"><button class="btn icon" type="button" onclick="$('#np-bc').value='50'+String(Math.floor(Math.random()*1e11)).padStart(11,'0')" title="Generate">${ic('refresh',16)}</button></div></label><label class="field">Expiry (days)<input class="input" type="number" id="np-exp" value="${p.expiry??180}"></label><label class="field full">Variants <small>(comma-separated)</small><input class="input" id="np-var" value="${(p.variants||[]).join(', ')}" placeholder="e.g. Small, Medium, Large"></label></div>`}
function addProduct(){modal({title:'Add product',sub:'Create a new item in the central catalog',icon:'package',size:'lg',body:productForm(),foot:`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn pri" onclick="saveProduct()">${ic('check',16,2.4)} Create product</button>`})}
function editProduct(id){modal({title:'Edit product',sub:'Price changes are recorded in the audit trail',icon:'edit',size:'lg',body:productForm(P(id)),foot:`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn pri" onclick="saveProduct(${id})">Save changes</button>`})}
function saveProduct(id){const g=k=>$('#np-'+k).value.trim();const name=g('name'),price=+g('price'),cost=+g('cost')||price*.55;if(!name||!(price>0))return toast('Name and a valid retail price are required','warn');const cat=g('cat');const data={name,cat,price,cost,wholesale:+g('whl')||r2(price*.86),min:+g('min')||20,max:+g('max')||150,barcode:g('bc')||'50'+String(Math.floor(Math.random()*1e11)).padStart(11,'0'),expiry:+g('exp')||180,variants:g('var')?g('var').split(',').map(s=>s.trim()).filter(Boolean):[]};if(id){const p=P(id);if(p.price!==price)audit('price',`Price changed · ${p.name} ${money(p.price)} → ${money(price)}`,p.sku);Object.assign(p,data);saveState();toast('Product updated')}else{const nid=Math.max(...S.products.map(p=>p.id))+1;const sku=g('sku')||CATS[cat].px+'-'+(100+nid*7);if(S.products.some(p=>p.sku.toLowerCase()===sku.toLowerCase()))return toast('That SKU already exists','err');S.products.push({id:nid,...data,sku,stock:Math.max(0,+g('stock')||0),emoji:'🛍️',sold30:0,batch:'B'+(2700+nid),extraBarcodes:[]});audit('stock','Product created · '+name,sku);toast(`<b>${esc(name)}</b> added to catalog`)}closeModal();if(S.page==='inventory')refresh()}
function importCSVPrompt(){modal({title:'Import products',sub:'Upload a CSV with columns: name, sku, category, price, stock',icon:'upload',body:`<label style="display:block;border:2px dashed var(--border-2);border-radius:18px;padding:34px;text-align:center;cursor:pointer;transition:.2s" onmouseover="this.style.borderColor='var(--primary)'" onmouseout="this.style.borderColor='var(--border-2)'"><div class="e-ic" style="width:56px;height:56px;margin:0 auto 12px;border-radius:16px;display:grid;place-items:center;background:var(--primary-soft);color:var(--primary)">${ic('upload',24)}</div><b>Choose a CSV file</b><div class="sm muted">or drag it here · max 5 MB</div><input type="file" accept=".csv,text/csv" style="display:none" onchange="importCSV(this.files[0])"></label><button class="btn sm ghost mt" onclick="exportCSV('import-template',[['name','sku','category','price','stock'],['Organic Granola 500g','GRC-900','Grocery','4.50','60']])">${ic('download',14)} Download template</button>`})}
function importCSV(file){if(!file)return;const rd=new FileReader();rd.onload=()=>{const rows=rd.result.replace(/^\ufeff/,'').split(/\r?\n/).filter(Boolean).map(l=>l.split(',').map(x=>x.replace(/^"|"$/g,'').trim()));const h=rows.shift().map(x=>x.toLowerCase());const ix=k=>h.indexOf(k);let n=0,skip=0;rows.forEach(r=>{const name=r[ix('name')],price=+r[ix('price')];if(!name||!(price>0)){skip++;return}const cat=CATS[r[ix('category')]]?r[ix('category')]:'Grocery';const nid=Math.max(...S.products.map(p=>p.id))+1;S.products.push({id:nid,name,cat,price,cost:r2(price*.55),wholesale:r2(price*.86),stock:+r[ix('stock')]||0,min:20,max:150,emoji:'🛍️',expiry:180,sold30:0,sku:r[ix('sku')]||CATS[cat].px+'-'+(100+nid*7),barcode:'50'+String(Math.floor(Math.random()*1e11)).padStart(11,'0'),batch:'B'+(2700+nid),variants:[],extraBarcodes:[]});n++});closeModal();audit('stock',`CSV import · ${n} products`,file.name);toast(`Imported <b>${n}</b> products${skip?` · ${skip} rows skipped`:''}`);if(S.page==='inventory')refresh()};rd.readAsText(file)}

/* ================= BRANCHES ================= */
S.bprice={};
PAGES.branches=()=>{const tr=S.transfers;return `<div class="page">${head('Network management','Multi-Branch','One connected business across every location — central catalog, branch pricing and stock transfers.',`<button class="btn" onclick="branchPricing()">${ic('tag',16)} Branch pricing</button><button class="btn pri" onclick="newTransfer()">${ic('swap',16)} New stock transfer</button>`)}<section class="grid g4 mb">${kpi('Network revenue (MTD)',cu(sum(S.branches,b=>b.rev),'money'),'+11.4%','store','var(--primary)',[5,6,6,7,8,7,9,10],0)}${kpi('Active stores',cu(S.branches.length),'','pin','var(--teal)',null,1,'all trading today')}${kpi('Transfers in transit',cu(tr.filter(t=>t.status==='In transit').length),'','truck','var(--warning)',null,2,tr.length+' this week')}${kpi('Branch employees',cu(sum(S.branches,b=>b.staff)),'+4','users','var(--pink)',null,3,'centrally managed')}</section><section class="grid g4 mb">${S.branches.map((b,i)=>{const p=b.rev/b.target*100;return `<div class="card branch-c hov rv" style="--i:${i+4};--c:${b.c}"><div class="bh"><div class="bi">${b.id}</div><div style="flex:1"><b class="display" style="font-size:15px">${b.name}</b><div class="xs muted">${b.manager} · ${b.staff} staff</div></div><span class="badge ok dot live">Open</span></div><div class="row between"><div><div class="xs muted">Revenue MTD</div><div class="display" style="font-size:24px;font-weight:800;letter-spacing:-.6px">${cu(b.rev,'moneyK')}</div></div>${spark(b.trend,b.c,96,40)}</div><div class="row between xs" style="margin:14px 0 6px"><span class="muted">Target ${moneyK(b.target)}</span><b style="color:${p>=100?'var(--success)':'var(--text)'}">${p.toFixed(0)}%</b></div><div class="progress"><i style="width:${Math.min(100,p)}%;background:${b.c};animation:growX 1.2s var(--ease) both;transform-origin:left"></i></div><div class="grid g3" style="gap:8px;margin-top:14px;text-align:center">${[['Orders',num(b.orders)],['Basket',money(b.rev/b.orders)],['Margin',(30+i*1.3).toFixed(1)+'%']].map(x=>`<div style="background:var(--surface-2);border-radius:10px;padding:8px 4px"><div class="xs muted">${x[0]}</div><b class="sm num">${x[1]}</b></div>`).join('')}</div><button class="btn sm" style="width:100%;margin-top:12px" onclick="$('#branch-sel').value='${b.name}';setBranch('${b.name}');go('overview')">Open dashboard ${ic('arrowR',14)}</button></div>`}).join('')}</section><div class="grid g-main mb"><section class="card pad rv" style="--i:8"><div class="ch"><div><h3>Performance comparison</h3><p>Revenue, orders and target attainment by store</p></div></div><div class="grid g2"><div>${bars(S.branches.map(b=>b.rev),S.branches.map(b=>b.name),{colors:S.branches.map(b=>b.c),h:220})}</div><div class="tw" style="margin:0"><table><thead><tr><th>Store</th><th class="tr">Revenue</th><th class="tr">vs target</th><th class="tr">Conversion</th></tr></thead><tbody>${[...S.branches].sort((a,b)=>b.rev-a.rev).map((b,i)=>`<tr><td><div class="row" style="gap:8px"><span class="rank r${i+1}">${i+1}</span><b>${b.name}</b></div></td><td class="tr num">${moneyK(b.rev)}</td><td class="tr"><span class="b ${b.rev>=b.target?'up':'down'}">${b.rev>=b.target?'+':''}${((b.rev/b.target-1)*100).toFixed(1)}%</span></td><td class="tr num">${(24+i*-2.1+8).toFixed(1)}%</td></tr>`).join('')}</tbody></table></div></div></section><section class="card pad rv" style="--i:9"><div class="ch"><div><h3>Stock transfers</h3><p>Branch-to-branch movements</p></div><button class="btn sm" onclick="newTransfer()">${ic('plus',14)} New</button></div>${tr.map(t=>{const p=P(t.pid);return `<div class="li"><div class="pimg" style="width:38px;height:38px;font-size:19px;background:${CATS[p.cat].tone}">${p.emoji}</div><div style="flex:1;min-width:0"><b class="sm">${t.id} · ${t.qty} × ${esc(p.name)}</b><div class="xs muted">${t.from} ${ic('arrowR',10)} ${t.to} · ${fmtTime(t.date)}</div></div>${t.status==='In transit'?`<button class="btn xs soft" onclick="receiveTransfer('${t.id}')">Receive</button>`:statusBadge(t.status)}</div>`}).join('')}</section></div>${foot()}</div>`};
function newTransfer(){modal({title:'New stock transfer',sub:'Move inventory between branches with a full audit trail',icon:'swap',body:`<div class="fgrid"><label class="field">From branch<select class="sel" id="tf-f">${S.branches.map(b=>`<option value="${b.id}">${b.name}</option>`).join('')}</select></label><label class="field">To branch<select class="sel" id="tf-t">${S.branches.map((b,i)=>`<option value="${b.id}" ${i===3?'selected':''}>${b.name}</option>`).join('')}</select></label><label class="field full">Product<select class="sel" id="tf-p">${S.products.map(p=>`<option value="${p.id}">${p.emoji} ${esc(p.name)} (${p.stock} available)</option>`).join('')}</select></label><label class="field">Quantity<input class="input" type="number" id="tf-q" value="12" min="1"></label><label class="field">Expected arrival<input class="input" type="date" id="tf-d" value="${new Date(Date.now()+DAY).toISOString().slice(0,10)}"></label></div>`,foot:`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn pri" onclick="saveTransfer()">${ic('truck',16)} Dispatch transfer</button>`})}
function saveTransfer(){const f=$('#tf-f').value,t=$('#tf-t').value,pid=+$('#tf-p').value,q=+$('#tf-q').value;if(f===t)return toast('Choose two different branches','warn');if(!(q>0))return toast('Enter a quantity','warn');const id='TR-0'+(319+S.transfers.length-3);S.transfers.unshift({id,from:f,to:t,pid,qty:q,status:'In transit',date:new Date()});S.movements.unshift({time:new Date(),pid,type:'Transfer out',qty:-q,reason:id,user:'Alex Morgan'});audit('stock',`Transfer ${id} dispatched · ${f} → ${t}`,q+' units');closeModal();toast(`Transfer <b>${id}</b> dispatched`);refresh()}
function receiveTransfer(id){const t=S.transfers.find(x=>x.id===id);t.status='Completed';S.movements.unshift({time:new Date(),pid:t.pid,type:'Transfer in',qty:t.qty,reason:id,user:'Hannah Scott'});audit('stock','Transfer received · '+id,t.to);toast(`${id} received at ${t.to}`);refresh()}
function branchPricing(){modal({title:'Branch-specific pricing',sub:'Override the central price list for individual stores',icon:'tag',size:'xl',body:`<div class="tw"><table><thead><tr><th>Product</th><th class="tr">Central</th>${S.branches.map(b=>`<th class="tr">${b.id}</th>`).join('')}</tr></thead><tbody>${S.products.slice(0,10).map(p=>`<tr><td><b>${p.emoji} ${esc(p.name)}</b></td><td class="tr num">${money(p.price)}</td>${S.branches.map(b=>`<td class="tr"><input class="input num" style="width:92px;height:34px;text-align:right" type="number" step=".01" placeholder="${p.price.toFixed(2)}" value="${S.bprice[b.id+p.id]||''}" onchange="S.bprice['${b.id}${p.id}']=this.value"></td>`).join('')}</tr>`).join('')}</tbody></table></div>`,foot:`<button class="btn" onclick="closeModal()">Close</button><button class="btn pri" onclick="audit('price','Branch price list updated','Multi-branch');closeModal();toast('Branch price lists published')">Publish price lists</button>`})}

/* ================= PURCHASING ================= */
S.pur='orders';
const poVal=po=>r2(sum(po.lines,l=>l.qty*l.cost));
PAGES.purchasing=()=>{const open=S.pos.filter(p=>p.status!=='Received');return `<div class="page">${head('Supply chain','Purchasing & Suppliers','Purchase orders, goods receiving, returns and supplier ledgers — with automatic stock updates.',`<button class="btn" onclick="exportCSV('purchase-orders',[['PO','Supplier','Value','Status','ETA'],...S.pos.map(p=>[p.id,S.suppliers.find(s=>s.id===p.sup).name,poVal(p),p.status,fmtDate(p.eta)])])">${ic('download',16)} Export</button><button class="btn pri" onclick="newPO()">${ic('plus',16,2.4)} New purchase order</button>`)}<section class="grid g4 mb">${kpi('Open purchase orders',cu(open.length),'','receipt','var(--primary)',null,0,moneyK(sum(open,poVal))+' committed')}${kpi('Awaiting delivery',cu(S.pos.filter(p=>p.status==='Ordered'||p.status==='Partially received').length),'','truck','var(--warning)',null,1,'next due tomorrow')}${kpi('Supplier balances',cu(sum(S.suppliers,s=>s.balance),'money'),'-6.2%','bank','var(--danger)',[8,7,7,6,7,6,5,5],2,'payable')}${kpi('Avg. on-time delivery',cu(sum(S.suppliers,s=>s.ontime)/S.suppliers.length,'pct'),'+2.1 pts','clock','var(--teal)',[6,6,7,7,8,8,8,9],3)}</section><section class="card pad rv" style="--i:4"><div class="row between wrap mb"><div class="seg">${[['orders','Purchase orders'],['suppliers','Suppliers'],['perf','Supplier performance']].map(([k,l])=>`<button class="${S.pur===k?'on':''}" onclick="S.pur='${k}';refresh()">${l}</button>`).join('')}</div>${S.pur==='suppliers'?`<button class="btn sm" onclick="addSupplier()">${ic('plus',14)} Add supplier</button>`:''}</div>${S.pur==='orders'?poTable():S.pur==='suppliers'?supTable():supPerf()}</section>${foot()}</div>`};
function poTable(){return `<div class="tw"><table><thead><tr><th>PO</th><th>Supplier</th><th>Lines</th><th class="tr">Value</th><th>Received</th><th>Expected</th><th>Status</th><th></th></tr></thead><tbody>${S.pos.map((po,i)=>{const s=S.suppliers.find(x=>x.id===po.sup);const q=sum(po.lines,l=>l.qty),r=sum(po.lines,l=>l.rec);return `<tr class="rv" style="--i:${i}"><td><b>${po.id}</b><div class="xs muted">${fmtDate(po.created)}</div></td><td>${s.name}</td><td>${po.lines.map(l=>P(l.pid).emoji).join(' ')} <span class="xs muted">${po.lines.length} items</span></td><td class="tr num"><b>${money(poVal(po))}</b></td><td><div class="row" style="gap:8px"><div class="bar-mini" style="width:70px;--c:var(--success)"><i style="width:${r/q*100}%"></i></div><span class="xs">${r}/${q}</span></div></td><td>${fmtDate(po.eta)}</td><td>${statusBadge(po.status)}</td><td class="tr">${po.status==='Draft'?`<button class="btn xs pri" onclick="sendPO('${po.id}')">${ic('mail',13)} Send</button>`:po.status!=='Received'?`<button class="btn xs soft" onclick="receivePO('${po.id}')">${ic('inbox',13)} Receive</button>`:`<button class="btn xs" onclick="returnPO('${po.id}')">${ic('undo',13)} Return</button>`}</td></tr>`}).join('')}</tbody></table></div>`}
function supTable(){return `<div class="tw"><table><thead><tr><th>Supplier</th><th>Category</th><th class="tr">Balance due</th><th>Lead time</th><th>On-time</th><th>Rating</th><th></th></tr></thead><tbody>${S.suppliers.map((s,i)=>`<tr class="rv" style="--i:${i}"><td><div class="row" style="gap:10px">${avatar(s.name,34)}<div><b>${s.name}</b><div class="xs muted">${s.contact} · ${s.email}</div></div></div></td><td>${s.cat}</td><td class="tr num"><b>${money(s.balance)}</b></td><td>${s.lead} days</td><td><div class="row" style="gap:8px"><div class="bar-mini" style="width:70px;--c:${s.ontime>92?'var(--success)':'var(--warning)'}"><i style="width:${s.ontime}%"></i></div><span class="xs b">${s.ontime}%</span></div></td><td><span style="color:#f5b10b">${'★'.repeat(Math.round(s.rating))}</span><span class="muted">${'★'.repeat(5-Math.round(s.rating))}</span> <span class="xs">${s.rating}</span></td><td class="tr"><button class="btn xs" onclick="paySupplier(${s.id})">${ic('bank',13)} Record payment</button></td></tr>`).join('')}</tbody></table></div>`}
function supPerf(){return `<div class="grid g2"><div><h4 class="display" style="margin:0 0 6px">On-time delivery rate</h4>${bars(S.suppliers.map(s=>s.ontime),S.suppliers.map(s=>s.name.split(' ')[0]),{fmt:v=>v+'%',colors:['#5b4cf0','#14b8a6','#f29a0b','#e5479a','#0e9fe0','#8b7ffa']})}</div><div><h4 class="display" style="margin:0 0 6px">Average lead time (days)</h4>${bars(S.suppliers.map(s=>s.lead),S.suppliers.map(s=>s.name.split(' ')[0]),{fmt:v=>v+'d',c:'var(--teal)'})}</div></div>`}
function newPO(pre){modal({title:'New purchase order',sub:'Create, approve and send to supplier',icon:'receipt',size:'lg',body:`<div class="fgrid"><label class="field">Supplier<select class="sel" id="po-s">${S.suppliers.map(s=>`<option value="${s.id}">${s.name}</option>`).join('')}</select></label><label class="field">Expected delivery<input class="input" type="date" id="po-d" value="${new Date(Date.now()+3*DAY).toISOString().slice(0,10)}"></label></div><div class="sec-t">Order lines</div><div id="po-lines">${(pre||[{pid:7,qty:40}]).map(l=>poLine(l)).join('')}</div><button class="btn sm ghost" onclick="$('#po-lines').insertAdjacentHTML('beforeend',poLine({pid:1,qty:24}))">${ic('plus',14)} Add line</button>`,foot:`<button class="btn" onclick="savePO(false)">Save as draft</button><button class="btn pri" onclick="savePO(true)">${ic('mail',16)} Approve & send</button>`})}
const poLine=l=>`<div class="row po-l" style="margin-bottom:8px"><select class="sel" style="flex:1">${S.products.map(p=>`<option value="${p.id}" ${p.id===l.pid?'selected':''}>${p.emoji} ${esc(p.name)} — cost ${money(p.cost)} · stock ${p.stock}</option>`).join('')}</select><input class="input num" type="number" value="${l.qty}" style="width:100px" min="1"><button class="btn icon ghost" onclick="this.parentElement.remove()">${ic('trash',15)}</button></div>`;
function savePO(send){const lines=$$('.po-l').map(r=>{const pid=+r.querySelector('select').value;return{pid,qty:+r.querySelector('input').value,cost:P(pid).cost,rec:0}}).filter(l=>l.qty>0);if(!lines.length)return toast('Add at least one line','warn');const id='PO-'+(2043+S.pos.length-5);S.pos.unshift({id,sup:+$('#po-s').value,status:send?'Ordered':'Draft',created:new Date(),eta:new Date($('#po-d').value),lines});audit('stock',`Purchase order ${id} ${send?'sent':'drafted'}`,money(sum(lines,l=>l.qty*l.cost)));closeModal();toast(`<b>${id}</b> ${send?'sent to supplier':'saved as draft'}`);if(S.page==='purchasing')refresh()}
function sendPO(id){S.pos.find(p=>p.id===id).status='Ordered';audit('stock','Purchase order sent · '+id);toast(id+' approved and emailed to supplier');refresh()}
function receivePO(id){const po=S.pos.find(p=>p.id===id);modal({title:'Goods receiving',sub:`${po.id} · ${S.suppliers.find(s=>s.id===po.sup).name}`,icon:'inbox',iconC:'var(--success)',size:'lg',body:`<div class="tw"><table><thead><tr><th>Product</th><th class="tr">Ordered</th><th class="tr">Already received</th><th>Receive now</th></tr></thead><tbody>${po.lines.map((l,k)=>`<tr><td><b>${P(l.pid).emoji} ${esc(P(l.pid).name)}</b></td><td class="tr">${l.qty}</td><td class="tr">${l.rec}</td><td><input class="input num rcv" data-k="${k}" type="number" min="0" max="${l.qty-l.rec}" value="${l.qty-l.rec}" style="width:100px;height:36px"></td></tr>`).join('')}</tbody></table></div><p class="xs muted mt">${ic('info',12)} Partial deliveries are supported — the PO stays open until every line is fully received. Stock updates instantly.</p>`,foot:`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn ok" onclick="saveReceive('${id}')">${ic('check',16,2.4)} Post receipt</button>`})}
function saveReceive(id){const po=S.pos.find(p=>p.id===id);let tot=0;$$('.rcv').forEach(inp=>{const l=po.lines[+inp.dataset.k];const q=Math.min(l.qty-l.rec,Math.max(0,+inp.value));if(q>0){l.rec+=q;P(l.pid).stock+=q;tot+=q;S.movements.unshift({time:new Date(),pid:l.pid,type:'Received',qty:q,reason:id,user:'Alex Morgan'})}});if(!tot)return toast('Nothing to receive','warn');po.status=po.lines.every(l=>l.rec>=l.qty)?'Received':'Partially received';const s=S.suppliers.find(x=>x.id===po.sup);s.balance=r2(s.balance+tot*po.lines[0].cost);audit('stock',`Goods received · ${id} (${tot} units)`,s.name);closeModal();toast(`${tot} units received into stock`);refresh()}
function returnPO(id){const po=S.pos.find(p=>p.id===id);modal({title:'Purchase return',sub:`Return goods to supplier against ${id}`,icon:'undo',size:'sm',body:`<label class="field">Product<select class="sel" id="pr-p">${po.lines.map(l=>`<option value="${l.pid}">${esc(P(l.pid).name)}</option>`).join('')}</select></label><label class="field mt">Quantity<input class="input" type="number" id="pr-q" value="5"></label><label class="field mt">Reason<select class="sel"><option>Damaged in transit</option><option>Short-dated</option><option>Wrong item</option></select></label>`,foot:`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn danger" onclick="const p=P(+$('#pr-p').value),q=+$('#pr-q').value;p.stock=Math.max(0,p.stock-q);S.movements.unshift({time:new Date(),pid:p.id,type:'Write-off',qty:-q,reason:'Return '+'${id}',user:'Alex Morgan'});const s=S.suppliers.find(x=>x.id===${po.sup});s.balance=Math.max(0,r2(s.balance-q*p.cost));audit('stock','Purchase return · ${id}',q+' units');closeModal();toast('Credit note raised · '+money(q*p.cost))">Raise credit note</button>`})}
function paySupplier(id){const s=S.suppliers.find(x=>x.id===id);modal({title:'Record supplier payment',sub:`${s.name} · balance ${money(s.balance)}`,size:'sm',icon:'bank',body:`<label class="field">Amount<input class="input" type="number" step=".01" id="sp-a" value="${s.balance.toFixed(2)}"></label><label class="field mt">Method<select class="sel"><option>Bank transfer (BACS)</option><option>Card</option><option>Cheque</option></select></label>`,foot:`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn pri" onclick="const a=+$('#sp-a').value;const s=S.suppliers.find(x=>x.id===${id});s.balance=Math.max(0,r2(s.balance-a));audit('settings','Supplier payment · '+s.name,money(a));closeModal();toast('Payment of '+money(a)+' recorded');refresh()">Record payment</button>`})}
function addSupplier(){modal({title:'Add supplier',icon:'truck',body:`<div class="fgrid"><label class="field full">Company name<input class="input" id="su-n"></label><label class="field">Contact name<input class="input" id="su-c"></label><label class="field">Category<select class="sel" id="su-cat">${Object.keys(CATS).map(c=>`<option>${c}</option>`).join('')}</select></label><label class="field">Email<input class="input" id="su-e" type="email"></label><label class="field">Lead time (days)<input class="input" id="su-l" type="number" value="3"></label></div>`,foot:`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn pri" onclick="if(!$('#su-n').value.trim())return toast('Enter a company name','warn');S.suppliers.push({id:S.suppliers.length+1,name:$('#su-n').value.trim(),contact:$('#su-c').value||'—',cat:$('#su-cat').value,balance:0,lead:+$('#su-l').value||3,ontime:100,rating:5,email:$('#su-e').value||'—',orders:0});saveState();closeModal();toast('Supplier added');refresh()">Add supplier</button>`})}

/* ================= CUSTOMERS ================= */
S.crm={q:'',g:'All'};
PAGES.customers=()=>{const bm=new Date().getMonth();const bdays=S.customers.filter(c=>new Date(c.birthday).getMonth()===bm||new Date(c.birthday).getMonth()===(bm+1)%12);return `<div class="page">${head('Customer intelligence','Customers & CRM','Profiles, purchase history, credit accounts and segments in one place.',`<button class="btn" onclick="exportCSV('customers',[['Name','Email','Phone','Tier','Group','Points','Spent','Credit'],...S.customers.map(c=>[c.name,c.email,c.phone,c.tier,c.group,c.points,c.spent.toFixed(2),c.credit])])">${ic('download',16)} Export</button><button class="btn pri" onclick="addCustomer()">${ic('userPlus',16)} Add customer</button>`)}<section class="grid g4 mb">${kpi('Total customers',cu(12836+S.customers.length),'+6.4%','users','var(--primary)',[4,5,5,6,6,7,8,8],0)}${kpi('Returning shoppers',cu(68.4,'pct'),'+2.3 pts','refresh','var(--teal)',[5,5,6,6,6,7,7,8],1)}${kpi('Avg. lifetime value',cu(384,'money'),'+9.1%','star','var(--warning)',[4,5,5,6,7,7,8,9],2)}${kpi('Credit outstanding',cu(sum(S.customers,c=>c.credit),'money'),'','wallet','var(--danger)',null,3,S.customers.filter(c=>c.credit>0).length+' accounts')}</section><div class="grid g-side"><section class="card pad rv" style="--i:4"><div class="row between wrap mb"><div class="seg">${['All','VIP','Retail','Trade','Wholesale','Staff'].map(g=>`<button class="${S.crm.g===g?'on':''}" onclick="S.crm.g='${g}';refresh()">${g}</button>`).join('')}</div><label class="search">${ic('search',16)}<input placeholder="Search customers…" value="${esc(S.crm.q)}" oninput="S.crm.q=this.value;$('#ctab').innerHTML=custTable()"></label></div><div id="ctab">${custTable()}</div></section><div class="grid" style="align-content:start"><section class="card pad rv" style="--i:5"><div class="ch"><div><h3>Customer groups</h3><p>Segment-specific pricing</p></div></div>${[['VIP','10% off · priority service','var(--primary)'],['Trade','Net-30 credit terms','var(--teal)'],['Wholesale','Wholesale price list','var(--warning)'],['Staff','15% staff discount','var(--pink)']].map(g=>`<div class="li"><div class="fic" style="--c:${g[2]}">${ic('users',15)}</div><div style="flex:1"><b class="sm">${g[0]}</b><div class="xs muted">${g[1]}</div></div><b class="num">${S.customers.filter(c=>c.group===g[0]).length}</b></div>`).join('')}</section><section class="card pad rv ai-glow" style="--i:6"><div class="ch"><div><h3>🎂 Birthday campaign</h3><p>${bdays.length} customers this month & next</p></div></div><div class="row" style="margin-bottom:14px">${bdays.slice(0,6).map(c=>`<div title="${esc(c.name)} · ${new Date(c.birthday).toLocaleDateString('en-GB',{day:'numeric',month:'short'})}" style="margin-right:-10px;border:2px solid var(--surface);border-radius:13px">${avatar(c.name,34)}</div>`).join('')}</div><button class="btn pri sm" style="width:100%" onclick="audit('settings','Birthday campaign sent',${bdays.length}+' customers');toast('Birthday offer (20% off) sent to ${bdays.length} customers by email & SMS')">${ic('gift',14)} Send birthday offer</button></section></div></div>${foot()}</div>`};
function custTable(){const q=S.crm.q.toLowerCase();const l=S.customers.filter(c=>(S.crm.g==='All'||c.group===S.crm.g)&&(c.name+c.email+c.phone).toLowerCase().includes(q));return l.length?`<div class="tw"><table><thead><tr><th>Customer</th><th>Tier</th><th>Group</th><th class="tr">Points</th><th class="tr">Lifetime spend</th><th class="tr">Visits</th><th class="tr">Credit</th></tr></thead><tbody>${l.map((c,i)=>`<tr class="click rv" style="--i:${i}" onclick="custDrawer(${c.id})"><td><div class="row" style="gap:10px">${avatar(c.name,34)}<div><b>${esc(c.name)}</b><div class="xs muted">${c.email}</div></div></div></td><td><span class="tier ${c.tier}">${ic('crown',11)} ${c.tier}</span></td><td>${c.group}</td><td class="tr num">${num(c.points)}</td><td class="tr num"><b>${money(c.spent)}</b></td><td class="tr num">${c.visits}</td><td class="tr num">${c.credit?`<span class="badge warn">${money(c.credit)}</span>`:'<span class="muted">—</span>'}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><div class="e-ic">${ic('users',26)}</div><b>No customers found</b></div>`}
function custDrawer(id){const c=C(id);const hist=S.orders.filter(o=>o.cid===id);const next={Silver:['Gold',1500],Gold:['Platinum',4000],Platinum:['Platinum',4000]}[c.tier];drawer(`<div class="dh">${avatar(c.name,56)}<div style="flex:1"><h2 class="display" style="margin:0;font-size:20px">${esc(c.name)}</h2><div class="sm muted">${c.email} · ${c.phone}</div><div class="row" style="gap:6px;margin-top:8px"><span class="tier ${c.tier}">${ic('crown',11)} ${c.tier}</span><span class="badge">${c.group}</span></div></div><button class="btn ghost sm icon" onclick="closeDrawer()">${ic('x',16)}</button></div><div class="db"><div class="kv"><div><small>Lifetime spend</small><b>${money(c.spent)}</b></div><div><small>Visits</small><b>${c.visits}</b></div><div><small>Loyalty points</small><b>${num(c.points)}</b></div><div><small>Avg. basket</small><b>${money(c.spent/Math.max(1,c.visits))}</b></div></div>${c.tier!=='Platinum'?`<div class="sec-t">Progress to ${next[0]}</div><div class="progress"><i style="width:${Math.min(100,c.points/next[1]*100)}%"></i></div><div class="xs muted" style="margin-top:6px">${num(Math.max(0,next[1]-c.points))} more points needed</div>`:''}<div class="sec-t">Credit account</div><div class="alert" style="--c:var(--warning)"><div class="fic" style="--c:var(--warning)">${ic('wallet',16)}</div><div style="flex:1"><b>${money(c.credit)} outstanding</b><small>Limit ${money(c.limit)} · ${c.credit>0?'Due in 14 days':'No balance due'}</small></div>${c.credit>0?`<button class="btn xs pri" onclick="settleCredit(${c.id})">Settle</button>`:''}</div><div class="sec-t">Purchase history</div>${hist.length?hist.slice(0,8).map(o=>`<div class="li click" style="cursor:pointer" onclick="closeDrawer();setTimeout(()=>orderDrawer('${o.id}'),260)"><div class="fic" style="--c:var(--primary)">${ic('receipt',15)}</div><div style="flex:1"><b class="sm">${o.inv}</b><div class="xs muted">${fmtTime(o.time)} · ${sum(o.items,i=>i.qty)} items</div></div><b class="num sm">${money(o.total)}</b></div>`).join(''):'<div class="muted sm">No purchases in the last 7 days.</div>'}<div class="sec-t">Details</div><div class="kv"><div><small>Birthday</small><b style="font-size:14px">${new Date(c.birthday).toLocaleDateString('en-GB',{day:'numeric',month:'long'})}</b></div><div><small>Customer since</small><b style="font-size:14px">${fmtDate(c.since)}</b></div></div></div><div class="df"><button class="btn" onclick="closeDrawer();S.cart.customer=${c.id};go('pos')">${ic('scan',15)} New sale</button><button class="btn" onclick="adjPoints(${c.id})">${ic('star',15)} Adjust points</button><button class="btn" onclick="toast('Message sent to ${esc(c.name.split(' ')[0])}')">${ic('mail',15)} Message</button></div>`)}
function settleCredit(id){const c=C(id);const a=c.credit;c.credit=0;audit('sale','Credit account settled · '+c.name,money(a));toast(`${money(a)} received from ${esc(c.name)}`);custDrawer(id);if(S.page==='customers')refresh()}
function adjPoints(id){const c=C(id);modal({title:'Adjust loyalty points',sub:esc(c.name)+' · '+num(c.points)+' pts',size:'sm',icon:'star',iconC:'var(--pink)',body:`<label class="field">Points (+ add / − remove)<input class="input" type="number" id="ap" value="100"></label><label class="field mt">Reason<input class="input" placeholder="Goodwill gesture" id="apr"></label>`,foot:`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn pri" onclick="const v=+$('#ap').value;C(${id}).points=Math.max(0,C(${id}).points+v);audit('settings','Points adjusted · ${esc(c.name)}',(v>0?'+':'')+v);closeModal();toast('Points updated');custDrawer(${id})">Save</button>`})}
function addCustomer(fromPos){modal({title:'New customer',sub:'Create a profile and enrol in loyalty',icon:'userPlus',body:`<div class="fgrid"><label class="field full">Full name<input class="input" id="nc-n" placeholder="Jane Smith"></label><label class="field">Email<input class="input" id="nc-e" type="email"></label><label class="field">Phone<input class="input" id="nc-p" placeholder="+44 7…"></label><label class="field">Group<select class="sel" id="nc-g"><option>Retail</option><option>VIP</option><option>Trade</option><option>Wholesale</option><option>Staff</option></select></label><label class="field">Credit limit<input class="input" type="number" id="nc-l" value="0"></label><label class="field full">Birthday<input class="input" type="date" id="nc-b"></label><label class="row sm full" style="gap:10px"><label class="switch"><input type="checkbox" checked><span></span></label> Marketing consent (email & SMS)</label></div>`,foot:`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn pri" onclick="saveCustomer(${!!fromPos})">${ic('check',16,2.4)} Create customer</button>`})}
function saveCustomer(fromPos){const n=$('#nc-n').value.trim();if(!n)return toast('Enter a name','warn');const id=S.customers.length+1;S.customers.unshift({id,name:n,tier:'Silver',points:50,credit:0,limit:+$('#nc-l').value||0,group:$('#nc-g').value,email:$('#nc-e').value||'—',phone:$('#nc-p').value||'—',spent:0,visits:0,birthday:$('#nc-b').value?new Date($('#nc-b').value):new Date(1990,0,1),since:new Date()});audit('user','Customer created · '+n);closeModal();toast(`<b>${esc(n)}</b> enrolled · 50 welcome points`);if(fromPos){S.cart.customer=id;drawCart()}else if(S.page==='customers')refresh()}

/* ================= LOYALTY ================= */
PAGES.loyalty=()=>`<div class="page">${head('Retention engine','Loyalty & Rewards','Points, tiers, gift cards, digital vouchers and coupons that bring customers back.',`<button class="btn" onclick="newCoupon()">${ic('ticket',16)} New coupon</button><button class="btn pri" onclick="issueGift()">${ic('gift',16)} Issue gift card</button>`)}<section class="grid g4 mb">${kpi('Active members',cu(4891),'+8.6%','users','var(--primary)',[4,5,5,6,7,7,8,9],0)}${kpi('Points issued (30d)',cu(128400),'+12%','star','var(--pink)',[5,5,6,6,7,8,8,9],1)}${kpi('Rewards redeemed',cu(836),'+5.2%','gift','var(--teal)',[4,5,4,6,5,6,7,7],2)}${kpi('Member revenue share',cu(61.8,'pct'),'+3.4 pts','trend','var(--warning)',[5,5,6,6,6,7,7,8],3)}</section><section class="grid g3 mb">${[['Silver','0 – 1,499 pts','1 pt per £1 · birthday reward','#9aa1b9','#5d647d',S.customers.filter(c=>c.tier==='Silver').length*312],['Gold','1,500 – 3,999 pts','1.25× points · 5% member price','#f6c453','#c27c0e',S.customers.filter(c=>c.tier==='Gold').length*121],['Platinum','4,000+ pts','1.5× points · 5% off · free delivery','#8b7ffa','#3a2bc4',S.customers.filter(c=>c.tier==='Platinum').length*88]].map((t,i)=>`<div class="tier-c rv hov card" style="--i:${i+4};--c1:${t[3]};--c2:${t[4]};border:0"><div class="row between"><span style="font-size:11px;letter-spacing:2px;font-weight:700;opacity:.85">MEMBERSHIP TIER</span>${ic('crown',22)}</div><div class="display" style="font-size:28px;font-weight:800;margin:16px 0 2px">${t[0]}</div><div style="opacity:.85;font-size:12.5px">${t[1]}</div><div class="row between" style="margin-top:22px"><span style="font-size:12px;opacity:.9">${t[2]}</span><b class="display" style="font-size:20px">${num(t[5])}</b></div></div>`).join('')}</section><div class="grid g-main mb"><section class="card pad rv" style="--i:7"><div class="ch"><div><h3>Gift cards & digital vouchers</h3><p>Stored-value cards redeemable in store and online</p></div><button class="btn sm" onclick="issueGift()">${ic('plus',14)} Issue</button></div><div class="grid g3">${S.giftcards.map((g,i)=>`<div class="gift-card rv" style="--i:${i};--c1:${g.c1};--c2:${g.c2}"><div class="row between"><b style="font:800 15px 'Plus Jakarta Sans',system-ui,sans-serif">monarch<span style="color:#d5fd79">.</span></b><span style="font-size:10px;letter-spacing:1.5px;opacity:.8">GIFT CARD</span></div><div><div class="display" style="font-size:26px;font-weight:800">${money(g.bal)}</div><div style="font-size:11px;opacity:.8">of ${money(g.init)} · ${esc(g.to)}</div></div><div class="row between"><span class="code">${g.code}</span><span style="font-size:10px;opacity:.8">EXP ${new Date(g.exp).toLocaleDateString('en-GB',{month:'2-digit',year:'2-digit'})}</span></div></div>`).join('')}</div></section><section class="card pad rv" style="--i:8"><div class="ch"><div><h3>Programme rules</h3><p>Applied automatically at checkout</p></div></div><label class="field">Points earned per ${CUR[S.settings.currency].trim()}1 spent<input class="input" type="number" step=".1" value="${S.settings.pointsPer}" onchange="S.settings.pointsPer=+this.value;saveState();toast('Earn rate updated')"></label><label class="field mt">Value of 1 point<input class="input" type="number" step=".001" value="${S.settings.pointValue}" onchange="S.settings.pointValue=+this.value;saveState();toast('Redemption value updated')"></label><div class="li mt"><div style="flex:1"><b class="sm">Points expire after 12 months</b><div class="xs muted">Inactive accounts only</div></div><label class="switch"><input type="checkbox" checked><span></span></label></div><div class="li"><div style="flex:1"><b class="sm">Double points weekends</b><div class="xs muted">Sat – Sun</div></div><label class="switch"><input type="checkbox"><span></span></label></div></section></div><section class="card pad rv" style="--i:9"><div class="ch"><div><h3>Coupons</h3><p>Codes customers can enter at checkout</p></div><button class="btn sm" onclick="newCoupon()">${ic('plus',14)} New coupon</button></div><div class="tw"><table><thead><tr><th>Code</th><th>Discount</th><th>Usage</th><th>Expires</th><th>Status</th><th class="tr">Active</th></tr></thead><tbody>${S.coupons.map((c,i)=>`<tr><td><b style="font-family:monospace;font-size:13px;letter-spacing:1px">${c.code}</b> <button class="btn xs ghost" onclick="navigator.clipboard&&navigator.clipboard.writeText('${c.code}');toast('Code copied')">${ic('copy',12)}</button></td><td>${c.pct}% off order</td><td><div class="row" style="gap:8px"><div class="bar-mini" style="width:90px"><i style="width:${c.uses/c.limit*100}%"></i></div><span class="xs">${c.uses} / ${c.limit}</span></div></td><td>${fmtDate(c.exp)}</td><td>${statusBadge(c.active?'Active':'Paused')}</td><td class="tr"><label class="switch"><input type="checkbox" ${c.active?'checked':''} onchange="S.coupons[${i}].active=this.checked;toast('Coupon ${c.code} '+(this.checked?'activated':'paused'));refresh()"><span></span></label></td></tr>`).join('')}</tbody></table></div></section>${foot()}</div>`;
function issueGift(){modal({title:'Issue gift card',sub:'Generate a new stored-value card',icon:'gift',iconC:'var(--pink)',size:'sm',body:`<label class="field">Value<div class="quick" style="margin:0 0 8px">${[10,25,50,100].map(v=>`<button class="chip" onclick="$('#gv').value=${v}">${money(v,0)}</button>`).join('')}</div><input class="input" type="number" id="gv" value="25"></label><label class="field mt">Recipient<input class="input" id="gr" placeholder="Name or company"></label>`,foot:`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn pri" onclick="saveGift()">Issue card</button>`})}
function saveGift(){const v=+$('#gv').value;if(!(v>0))return toast('Enter a value','warn');const rc=()=>Math.random().toString(36).slice(2,6).toUpperCase();const pal=[['#6a5cf6','#3a2bc4'],['#14b8a6','#0e7490'],['#f29a0b','#e5479a'],['#e9445a','#7c3aed']][S.giftcards.length%4];const code=`GC-${rc()}-${rc()}`;S.giftcards.unshift({code,bal:v,init:v,to:$('#gr').value||'Walk-in customer',exp:new Date(Date.now()+365*DAY),c1:pal[0],c2:pal[1]});audit('sale','Gift card issued · '+code,money(v));closeModal();toast(`Gift card <b>${code}</b> issued`);refresh()}
function newCoupon(){modal({title:'New coupon',size:'sm',icon:'ticket',body:`<label class="field">Code<input class="input" id="cc" style="text-transform:uppercase" placeholder="SUMMER20"></label><div class="fgrid mt"><label class="field">Discount %<input class="input" type="number" id="cp" value="15"></label><label class="field">Usage limit<input class="input" type="number" id="cl" value="500"></label></div>`,foot:`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn pri" onclick="const c=$('#cc').value.trim().toUpperCase();if(!c)return toast('Enter a code','warn');S.coupons.unshift({code:c,pct:+$('#cp').value,uses:0,limit:+$('#cl').value,active:true,exp:new Date(Date.now()+60*DAY)});saveState();closeModal();toast('Coupon '+c+' created');refresh()">Create</button>`})}

/* ================= PROMOTIONS ================= */
const PTYPES={bxgy:['Buy X Get Y','gift','var(--pink)'],pct_cat:['Category discount','layers','var(--teal)'],pct_prod:['Product discount','tag','var(--primary)'],tiered:['Buy more, save more','trend','var(--warning)'],bundle:['Bundle / combo','package','var(--info)'],group:['Customer-group pricing','users','var(--primary)']};
function promoDesc(p){return p.type==='bxgy'?(p.x===1&&p.y===1?'Buy 1 get 1 free':`Buy ${p.x}, get ${p.y} free`)+' · '+esc(P(p.pid).name):p.type==='pct_cat'?`${p.pct}% off everything in ${p.cat}`:p.type==='pct_prod'?`${p.pct}% off ${esc(P(p.pid).name)}`:p.type==='tiered'?`${p.pct}% off baskets over ${money(p.min,0)}`:p.type==='bundle'?`${money(p.off)} off when bought together: ${p.pids.map(i=>P(i).name).join(' + ')}`:`${p.pct}% off for ${p.tiers.join(' & ')} members`}
PAGES.promotions=()=>`<div class="page">${head('Growth toolkit','Promotions & Pricing','A rules-based pricing engine — every active promotion applies automatically at the till.',`<button class="btn" onclick="go('pos')">${ic('scan',16)} Test in POS</button><button class="btn pri" onclick="newPromo()">${ic('plus',16,2.4)} New promotion</button>`)}<section class="grid g4 mb">${kpi('Live promotions',cu(S.promotions.filter(p=>p.active).length),'','zap','var(--primary)',null,0,'of '+S.promotions.length+' configured')}${kpi('Promo-driven revenue',cu(sum(S.promotions,p=>p.rev),'money'),'+18.2%','trend','var(--teal)',[4,5,6,6,7,8,9,10],1,'last 30 days')}${kpi('Redemptions',cu(sum(S.promotions,p=>p.uses)),'+9.4%','ticket','var(--pink)',[5,5,6,7,7,8,8,9],2)}${kpi('Avg. discount rate',cu(6.8,'pct'),'-0.4 pts','percent','var(--warning)',[7,7,6,7,6,6,6,5],3)}</section><section class="grid g3">${S.promotions.map((p,i)=>{const t=PTYPES[p.type];return `<div class="card mod-card hov rv" style="--i:${i+4};--c:${t[2]};${p.active?'':'opacity:.75'}"><div class="row between"><div class="mi">${ic(t[1],21)}</div><label class="switch" title="Active"><input type="checkbox" ${p.active?'checked':''} onchange="togglePromo(${p.id},this.checked)"><span></span></label></div><div><span class="badge" style="background:color-mix(in srgb,${t[2]} 13%,transparent);color:${t[2]}">${t[0]}</span><h3 class="display" style="margin:10px 0 4px;font-size:16px">${esc(p.name)}</h3><p class="sm muted" style="margin:0;min-height:38px">${promoDesc(p)}</p></div><div class="divider" style="margin:4px 0"></div><div class="row between sm"><span class="muted row" style="gap:6px">${ic('calendar',14)} ${p.sched}</span>${statusBadge(p.active?'Active':'Paused')}</div><div class="grid g2" style="gap:8px">${[['Redemptions',num(p.uses)],['Revenue',moneyK(p.rev)]].map(x=>`<div style="background:var(--surface-2);border-radius:10px;padding:9px 11px"><div class="xs muted">${x[0]}</div><b class="num">${x[1]}</b></div>`).join('')}</div></div>`}).join('')}</section>${foot()}</div>`;
function togglePromo(id,on){const p=S.promotions.find(x=>x.id===id);p.active=on;audit('price',`Promotion ${on?'activated':'paused'} · ${p.name}`);toast(`<b>${esc(p.name)}</b> ${on?'is now live at every till':'paused'}`,on?'ok':'info');setTimeout(refresh,250)}
function newPromo(){modal({title:'New promotion',sub:'Configure rules, targeting and schedule',icon:'zap',size:'lg',body:`<div class="fgrid"><label class="field full">Promotion name<input class="input" id="pn" placeholder="e.g. Summer drinks 3 for 2"></label><label class="field">Type<select class="sel" id="pt" onchange="promoFields()">${Object.entries(PTYPES).map(([k,v])=>`<option value="${k}">${v[0]}</option>`).join('')}</select></label><label class="field">Schedule<select class="sel" id="ps"><option>Always on</option><option>Weekends · Sat – Sun</option><option>Daily · 17:00–19:00 (happy hour)</option><option>Seasonal · 1 – 31 Dec</option><option>Limited time · next 7 days</option></select></label><div class="full" id="pf"></div></div>`,foot:`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn pri" onclick="savePromo()">${ic('zap',16)} Launch promotion</button>`});promoFields()}
function promoFields(){const t=$('#pt').value;const prodSel=id=>`<select class="sel" id="${id}">${S.products.map(p=>`<option value="${p.id}">${p.emoji} ${esc(p.name)}</option>`).join('')}</select>`;$('#pf').innerHTML=`<div class="fgrid">${t==='bxgy'?`<label class="field full">Product${prodSel('pp')}</label><label class="field">Buy quantity (X)<input class="input" type="number" id="px" value="2"></label><label class="field">Get free (Y)<input class="input" type="number" id="py" value="1"></label>`:t==='pct_cat'?`<label class="field">Category<select class="sel" id="pc">${Object.keys(CATS).map(c=>`<option>${c}</option>`).join('')}</select></label><label class="field">Discount %<input class="input" type="number" id="pv" value="15"></label>`:t==='pct_prod'?`<label class="field">Product${prodSel('pp')}</label><label class="field">Discount %<input class="input" type="number" id="pv" value="20"></label>`:t==='tiered'?`<label class="field">Minimum basket<input class="input" type="number" id="pm" value="40"></label><label class="field">Discount %<input class="input" type="number" id="pv" value="5"></label>`:t==='bundle'?`<label class="field">Product A${prodSel('pa')}</label><label class="field">Product B${prodSel('pb')}</label><label class="field">Bundle saving (amount)<input class="input" type="number" id="po" value="1.50" step=".01"></label>`:`<label class="field">Member tiers<select class="sel" id="pg"><option value="Gold,Platinum">Gold & Platinum</option><option value="Platinum">Platinum only</option><option value="Silver,Gold,Platinum">All members</option></select></label><label class="field">Discount %<input class="input" type="number" id="pv" value="5"></label>`}</div>`}
function savePromo(){const t=$('#pt').value,n=$('#pn').value.trim()||PTYPES[t][0];const p={id:Math.max(...S.promotions.map(x=>x.id))+1,name:n,type:t,active:true,sched:$('#ps').value,uses:0,rev:0};const v=k=>+$('#'+k).value;if(t==='bxgy')Object.assign(p,{pid:v('pp'),x:v('px'),y:v('py')});if(t==='pct_cat')Object.assign(p,{cat:$('#pc').value,pct:v('pv')});if(t==='pct_prod')Object.assign(p,{pid:v('pp'),pct:v('pv')});if(t==='tiered')Object.assign(p,{min:v('pm'),pct:v('pv')});if(t==='bundle')Object.assign(p,{pids:[v('pa'),v('pb')],off:v('po')});if(t==='group')Object.assign(p,{tiers:$('#pg').value.split(','),pct:v('pv')});S.promotions.unshift(p);audit('price','Promotion launched · '+n);closeModal();toast(`<b>${esc(n)}</b> is live`);if(S.page==='promotions')refresh()}

/* ================= EMPLOYEES ================= */
S.emp='team';
PAGES.employees=()=>`<div class="page">${head('People & access','Team & Permissions','Roles, granular permissions, shifts, commissions and login security.',`<button class="btn" onclick="S.emp='perm';refresh()">${ic('lock',16)} Permissions</button><button class="btn pri" onclick="inviteUser()">${ic('userPlus',16)} Invite team member</button>`)}<section class="grid g4 mb">${kpi('Team members',cu(126),'+4','users','var(--primary)',null,0,S.employees.length+' shown')}${kpi('On shift now',cu(S.employees.filter(e=>e.onShift).length+28),'','clock','var(--success)',null,1,'across 4 stores')}${kpi('Sales per labour hour',cu(142.6,'money'),'+6.1%','trend','var(--teal)',[5,5,6,6,7,7,7,8],2)}${kpi('Commission (MTD)',cu(sum(S.employees,e=>e.sales*e.comm/100)*22,'money'),'','wallet','var(--warning)',null,3,'payable 30 Nov')}</section><section class="card pad rv" style="--i:4"><div class="row between wrap mb"><div class="seg">${[['team','Team'],['perm','Roles & permissions'],['shifts','Shifts & attendance'],['logins','Login activity']].map(([k,l])=>`<button class="${S.emp===k?'on':''}" onclick="S.emp='${k}';refresh()">${l}</button>`).join('')}</div></div>${S.emp==='team'?teamTable():S.emp==='perm'?permMatrix():S.emp==='shifts'?shiftChart():loginTable()}</section>${foot()}</div>`;
function teamTable(){return `<div class="tw"><table><thead><tr><th>Member</th><th>Role</th><th>Branch</th><th>Status</th><th class="tr">Sales today</th><th class="tr">Transactions</th><th class="tr">Commission</th><th>Last login</th><th></th></tr></thead><tbody>${S.employees.map((e,i)=>`<tr class="rv" style="--i:${i}"><td><div class="row" style="gap:10px">${avatar(e.name,34)}<div><b>${e.name}</b><div class="xs muted">${e.email}</div></div></div></td><td><span class="badge ${e.role==='Owner'?'pri':e.role==='Manager'?'info':''}">${e.role}</span></td><td>${e.branch}</td><td>${e.onShift?'<span class="badge ok dot live">On shift</span>':'<span class="badge dot">Off</span>'}</td><td class="tr num">${e.sales?money(e.sales):'—'}</td><td class="tr num">${e.sales?e.txns:'—'}</td><td class="tr num">${e.comm?money(e.sales*e.comm/100):'—'}</td><td class="xs">${ago(e.last)}</td><td class="tr"><button class="btn xs" onclick="editEmp(${e.id})">${ic('edit',13)} Edit</button></td></tr>`).join('')}</tbody></table></div>`}
function permMatrix(){return `<p class="sm muted" style="margin:-4px 0 14px">Changes apply immediately to every register and device. Least-privilege by default.</p><div class="tw"><table class="perm-t"><thead><tr><th>Permission</th>${S.roles.map(r=>`<th style="text-align:center">${r}</th>`).join('')}</tr></thead><tbody>${S.perms.map(([k,l])=>`<tr><td><b>${l}</b></td>${S.roles.map(r=>`<td><label class="switch"><input type="checkbox" ${S.matrix[r].split(' ').includes(k)?'checked':''} ${r==='Owner'?'disabled':''} onchange="setPerm('${r}','${k}',this.checked)"><span></span></label></td>`).join('')}</tr>`).join('')}</tbody></table></div><button class="btn sm mt" onclick="customRole()">${ic('plus',14)} Create custom role</button>`}
function setPerm(r,k,on){let a=S.matrix[r].split(' ').filter(Boolean);a=on?[...new Set([...a,k])]:a.filter(x=>x!==k);S.matrix[r]=a.join(' ');audit('user',`Permission ${on?'granted':'revoked'} · ${r}: ${S.perms.find(p=>p[0]===k)[1]}`);toast(`${r}: ${S.perms.find(p=>p[0]===k)[1]} ${on?'granted':'revoked'}`,on?'ok':'info')}
function customRole(){modal({title:'Create custom role',size:'sm',icon:'key',body:`<label class="field">Role name<input class="input" id="rn" placeholder="e.g. Shift Supervisor"></label>`,foot:`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn pri" onclick="const n=$('#rn').value.trim();if(!n)return;S.roles.push(n);S.matrix[n]='sale disc10';saveState();closeModal();toast('Role '+n+' created');refresh()">Create</button>`})}
function shiftChart(){const hrs=Array.from({length:15},(_,i)=>7+i);return `<div style="overflow-x:auto"><div style="min-width:760px"><div style="display:grid;grid-template-columns:190px 1fr;gap:10px;margin-bottom:8px"><div></div><div style="display:grid;grid-template-columns:repeat(15,1fr)" class="xs muted">${hrs.map(h=>`<span>${String(h).padStart(2,'0')}:00</span>`).join('')}</div></div>${S.employees.map((e,i)=>{const st=7+(i*3)%5,len=e.onShift?6+(i%3):0;const nowH=new Date().getHours()+new Date().getMinutes()/60;return `<div style="display:grid;grid-template-columns:190px 1fr;gap:10px;align-items:center;margin-bottom:8px"><div class="row" style="gap:9px">${avatar(e.name,28)}<span class="sm b">${e.name}</span></div><div style="position:relative;height:30px;background:repeating-linear-gradient(90deg,var(--surface-2) 0,var(--surface-2) calc(100%/15 - 1px),var(--border) calc(100%/15));border-radius:8px">${len?`<div style="position:absolute;left:${(st-7)/15*100}%;width:${len/15*100}%;top:4px;bottom:4px;border-radius:7px;background:linear-gradient(90deg,${['#5b4cf0','#14b8a6','#f29a0b','#e5479a'][i%4]},${['#8b7ffa','#5eead4','#fbbf24','#f472b6'][i%4]});animation:growX .9s ${i*.06}s var(--ease) both;transform-origin:left;color:#fff;font-size:10.5px;font-weight:700;display:flex;align-items:center;padding-left:8px">${String(st).padStart(2,'0')}:00 – ${String(st+len).padStart(2,'0')}:00</div>`:`<div class="xs muted" style="position:absolute;left:8px;top:7px">Day off</div>`}${nowH>7&&nowH<22?`<div style="position:absolute;left:${(nowH-7)/15*100}%;top:-4px;bottom:-4px;width:2px;background:var(--danger)"></div>`:''}</div></div>`}).join('')}</div></div><div class="row mt sm muted" style="gap:16px"><span class="row" style="gap:6px"><span style="width:12px;height:2px;background:var(--danger)"></span> Current time</span><span>Clock-in / out tracked from POS login</span></div>`}
function loginTable(){return `<div class="tw"><table><thead><tr><th>User</th><th>Role</th><th>Device</th><th>IP address</th><th>Time</th><th>Result</th></tr></thead><tbody>${S.logins.map((l,i)=>`<tr class="rv" style="--i:${i}"><td><div class="row" style="gap:9px">${avatar(l.who,28)}<b>${l.who}</b></div></td><td>${l.role}</td><td>${l.dev}</td><td style="font-family:monospace">${l.ip}</td><td>${fmtTime(l.time)}</td><td>${l.ok?'<span class="badge ok dot">Success</span>':'<span class="badge bad dot">Failed · wrong PIN</span>'}</td></tr>`).join('')}</tbody></table></div>`}
function inviteUser(){modal({title:'Invite team member',sub:'They’ll receive an email to set up their account and PIN',icon:'userPlus',body:`<div class="fgrid"><label class="field full">Full name<input class="input" id="iu-n"></label><label class="field full">Work email<input class="input" id="iu-e" type="email"></label><label class="field">Role<select class="sel" id="iu-r">${S.roles.filter(r=>r!=='Owner').map(r=>`<option>${r}</option>`).join('')}</select></label><label class="field">Branch<select class="sel" id="iu-b">${S.branches.map(b=>`<option value="${b.id}">${b.name}</option>`).join('')}</select></label></div>`,foot:`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn pri" onclick="const n=$('#iu-n').value.trim();if(!n)return toast('Enter a name','warn');S.employees.push({id:S.employees.length+1,name:n,role:$('#iu-r').value,branch:$('#iu-b').value,onShift:false,sales:0,txns:0,comm:1,last:new Date(),email:$('#iu-e').value||n.toLowerCase().replace(/ /g,'.')+'@monarch-retail.co.uk',active:true});audit('user','User invited · '+n,$('#iu-r').value);closeModal();toast('Invitation sent to '+n);refresh()">${ic('mail',16)} Send invite</button>`})}
function editEmp(id){const e=S.employees.find(x=>x.id===id);modal({title:'Edit '+e.name,size:'sm',icon:'user',body:`<label class="field">Role<select class="sel" id="ee-r">${S.roles.map(r=>`<option ${r===e.role?'selected':''}>${r}</option>`).join('')}</select></label><label class="field mt">Commission %<input class="input" type="number" step=".1" id="ee-c" value="${e.comm}"></label><div class="li mt"><span style="flex:1" class="sm b">Account active</span><label class="switch"><input type="checkbox" checked><span></span></label></div><button class="btn sm ghost" onclick="toast('PIN reset link sent to ${e.email}')">${ic('key',14)} Reset POS PIN</button>`,foot:`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn pri" onclick="const e=S.employees.find(x=>x.id===${id});const o=e.role;e.role=$('#ee-r').value;e.comm=+$('#ee-c').value;if(o!==e.role)audit('user','Role updated · '+e.name+' → '+e.role);saveState();closeModal();toast('Team member updated');refresh()">Save</button>`})}

/* ================= REGISTERS ================= */
S.zreports=[{reg:'REG-02',who:'Sarah Collins',time:new Date(Date.now()-20*36e5),expected:812.4,counted:810.0},{reg:'REG-03',who:'Priya Shah',time:new Date(Date.now()-21*36e5),expected:654.1,counted:654.1},{reg:'REG-01',who:'Daniel Reed',time:new Date(Date.now()-44*36e5),expected:903.75,counted:913.75}];
const expCash=r=>r2(r.float+r.cash+r.cin-r.cout);
PAGES.registers=()=>{const open=S.registers.filter(r=>r.open);return `<div class="page">${head('Cash control','Cash & Registers','Opening floats, cash movements, shift closing and tender reconciliation for every till.',`<button class="btn" onclick="exportCSV('z-reports',[['Register','Closed by','Time','Expected','Counted','Variance'],...S.zreports.map(z=>[z.reg,z.who,new Date(z.time).toLocaleString('en-GB'),z.expected,z.counted,r2(z.counted-z.expected)])])">${ic('download',16)} Z-reports</button>`)}<section class="grid g4 mb">${kpi('Open registers',cu(open.length),'','monitor','var(--primary)',null,0,'of '+S.registers.length+' configured')}${kpi('Expected cash in drawers',cu(sum(open,expCash),'money'),'','cash','var(--success)',null,1,'incl. floats')}${kpi('Card & digital takings',cu(sum(open,r=>r.card+r.digital),'money'),'+9.8%','card','var(--teal)',[5,6,6,7,7,8,8,9],2)}${kpi('Variance (last 7 days)',cu(sum(S.zreports,z=>z.counted-z.expected),'money'),'','alert','var(--warning)',null,3,'within tolerance')}</section><section class="grid g4 mb">${S.registers.map((r,i)=>`<div class="card pad hov rv" style="--i:${i+4}"><div class="row between"><div class="row" style="gap:10px"><div class="kpi-ic" style="--c:${r.open?'var(--success)':'var(--text-3)'}">${ic('monitor',18)}</div><div><b class="display">${r.id}</b><div class="xs muted">${r.name} · ${r.branch}</div></div></div>${r.open?'<span class="badge ok dot live">Open</span>':'<span class="badge dot">Closed</span>'}</div>${r.open?`<div class="sm muted" style="margin:14px 0 10px">${ic('user',12)} ${r.cashier} · opened ${ago(r.opened)}</div><div class="ml"><span>Opening float</span><b>${money(r.float)}</b></div><div class="ml"><span>Cash sales</span><b>${money(r.cash)}</b></div><div class="ml"><span>Cash in / out</span><b>${money(r.cin)} / −${money(r.cout)}</b></div><div class="ml"><span>Card · Digital</span><b>${money(r.card)} · ${money(r.digital)}</b></div><div class="ml tot" style="font-size:13px"><span>Expected cash</span><b style="font-size:18px">${money(expCash(r))}</b></div><div class="grid g2" style="gap:8px;margin-top:12px"><button class="btn sm" onclick="cashMove('${r.id}')">${ic('swap',14)} Cash in/out</button><button class="btn sm dark" onclick="closeShift('${r.id}')">${ic('lock',14)} Close shift</button></div>`:`<div class="empty" style="padding:26px 0"><div class="sm">Register closed</div></div><button class="btn sm pri" style="width:100%" onclick="openReg('${r.id}')">${ic('play',14)} Open register</button>`}</div>`).join('')}</section><section class="card pad rv" style="--i:8"><div class="ch"><div><h3>Shift closings (Z-reports)</h3><p>Expected vs counted cash with variance tracking</p></div></div><div class="tw"><table><thead><tr><th>Register</th><th>Closed by</th><th>Time</th><th class="tr">Expected</th><th class="tr">Counted</th><th class="tr">Variance</th><th></th></tr></thead><tbody>${S.zreports.map(z=>{const v=r2(z.counted-z.expected);return `<tr><td><b>${z.reg}</b></td><td>${z.who}</td><td>${fmtTime(z.time)}</td><td class="tr num">${money(z.expected)}</td><td class="tr num">${money(z.counted)}</td><td class="tr"><span class="badge ${v===0?'ok':Math.abs(v)<5?'warn':'bad'}">${v>0?'+':''}${money(v)}</span></td><td class="tr"><button class="btn xs ghost" onclick="toast('Z-report sent to printer')">${ic('printer',13)}</button></td></tr>`}).join('')}</tbody></table></div></section>${foot()}</div>`};
function cashMove(id){modal({title:'Cash in / out',sub:id+' · non-sale cash movements',size:'sm',icon:'swap',body:`<div class="seg" id="cm-s" style="margin-bottom:14px"><button class="on" onclick="window._cm='in';$$('#cm-s button').forEach(b=>b.classList.remove('on'));this.classList.add('on')">Cash in</button><button onclick="window._cm='out';$$('#cm-s button').forEach(b=>b.classList.remove('on'));this.classList.add('on')">Cash out</button></div><label class="field">Amount<input class="input" type="number" step=".01" id="cm-a" value="20.00"></label><label class="field mt">Reason<select class="sel" id="cm-r"><option>Float top-up</option><option>Petty cash — supplies</option><option>Safe drop</option><option>Bank deposit</option></select></label>`,foot:`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn pri" onclick="const r=S.registers.find(x=>x.id==='${id}'),a=+$('#cm-a').value;if((window._cm||'in')==='in')r.cin+=a;else r.cout+=a;audit('settings','Cash '+(window._cm||'in')+' · ${id} · '+$('#cm-r').value,money(a));window._cm='in';closeModal();toast('Cash movement recorded · '+money(a));toast('Cash drawer opened','info');refresh()">Record</button>`});window._cm='in'}
function openReg(id){modal({title:'Open '+id,sub:'Count and confirm the opening float',size:'sm',icon:'play',body:`<label class="field">Cashier<select class="sel" id="or-c">${CASHIERS.map(c=>`<option>${c}</option>`).join('')}</select></label><label class="field mt">Opening float<input class="input" type="number" id="or-f" value="150.00"></label>`,foot:`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn pri" onclick="Object.assign(S.registers.find(x=>x.id==='${id}'),{open:true,cashier:$('#or-c').value,float:+$('#or-f').value,cash:0,cin:0,cout:0,card:0,digital:0,opened:new Date()});audit('settings','Register opened · ${id}');closeModal();toast('${id} is open for trading');refresh()">Open register</button>`})}
const DENOMS=[50,20,10,5,2,1,.5,.2,.1,.05];
function closeShift(id){const r=S.registers.find(x=>x.id===id);const exp=expCash(r);modal({title:'Close shift · '+id,sub:`${r.cashier} · count the drawer by denomination`,icon:'lock',size:'lg',body:`<div class="grid g2"><div><div class="grid g2" style="gap:8px">${DENOMS.map(d=>`<label class="row" style="gap:8px;background:var(--surface-2);border-radius:11px;padding:6px 8px"><span class="b sm" style="width:56px">${d>=1?money(d,0):Math.round(d*100)+'p'}</span><span class="muted">×</span><input class="input num dn" data-d="${d}" type="number" min="0" style="height:34px" placeholder="0" oninput="zCalc(${exp})"></label>`).join('')}</div></div><div><div class="due" style="flex-direction:column;align-items:stretch;gap:14px"><div class="row between"><div><small>EXPECTED</small><b style="font-size:24px">${money(exp)}</b></div><div style="text-align:right"><small>COUNTED</small><b style="font-size:24px" id="z-c">${money(0)}</b></div></div><div style="border-top:1px dashed #ffffff30;padding-top:12px"><small>VARIANCE</small><b id="z-v" style="font-size:30px">${money(-exp)}</b></div></div><div class="sec-t">Tender reconciliation</div><div class="ml"><span>${ic('card',13)} Card (terminal batch)</span><b>${money(r.card)} ✓</b></div><div class="ml"><span>${ic('phone',13)} Digital & bank</span><b>${money(r.digital)} ✓</b></div><label class="field mt">Variance note<input class="input" id="z-n" placeholder="Required if variance exceeds ${money(5)}"></label><button class="btn sm ghost mt" onclick="$$('.dn').forEach(i=>i.value='');const e=${exp};let rem=Math.round(e*100);DENOMS.forEach(d=>{const c=Math.floor(rem/Math.round(d*100));if(c){$('.dn[data-d=&quot;'+d+'&quot;]').value=c;rem-=c*Math.round(d*100)}});zCalc(e)">${ic('zap',14)} Auto-fill exact count (demo)</button></div></div>`,foot:`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn dark" onclick="saveZ('${id}',${exp})">${ic('printer',16)} Close & print Z-report</button>`})}
function zCalc(exp){const c=r2(sum($$('.dn'),i=>(+i.value||0)*+i.dataset.d));const v=r2(c-exp);$('#z-c').textContent=money(c);const el=$('#z-v');el.textContent=(v>0?'+':'')+money(v);el.style.color=Math.abs(v)<.01?'#7ef0c4':Math.abs(v)<5?'#ffc163':'#ff8a9a';window._zc=c}
function saveZ(id,exp){const c=window._zc||0;const v=r2(c-exp);if(Math.abs(v)>5&&!$('#z-n').value.trim())return toast('Add a note to explain the variance','warn');const r=S.registers.find(x=>x.id===id);S.zreports.unshift({reg:id,who:r.cashier,time:new Date(),expected:exp,counted:c});Object.assign(r,{open:false,cashier:'—'});audit('settings',`Shift closed · ${id} · variance ${money(v)}`);if(Math.abs(v)>5)S.suspicious.unshift({id:Date.now(),type:'Cash variance '+money(v),who:S.zreports[0].who,ref:id,amount:Math.abs(v),risk:Math.min(95,40+Math.abs(v)*3),time:new Date(),status:'Open'});window._zc=0;closeModal();toast(`${id} closed · variance <b>${money(v)}</b>`,Math.abs(v)<5?'ok':'warn');refresh()}
